-- One row per distinct delivery address. Orders are not stored; they are read from Ours24 each time.
-- address_key is a SHA-256 hex of the normalized address (see AddressKey.kt), so the same address that
-- arrives in many Jobs is one row. Do not edit this file after it is merged; add V2__... instead.
CREATE TABLE address_location (
    address_key  CHAR(64) PRIMARY KEY,
    address1     TEXT NOT NULL,
    address2     TEXT NOT NULL DEFAULT '',
    postal_code  TEXT NOT NULL DEFAULT '',
    company_name TEXT NOT NULL DEFAULT '',
    address_ko   TEXT,
    lat          DOUBLE PRECISION,
    lng          DOUBLE PRECISION,
    status       TEXT NOT NULL DEFAULT 'PENDING',
    created_at   TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at   TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT address_location_status CHECK (status IN ('PENDING', 'DONE', 'FAILED')),
    CONSTRAINT address_location_lat CHECK (lat IS NULL OR (lat >= -90 AND lat <= 90)),
    CONSTRAINT address_location_lng CHECK (lng IS NULL OR (lng >= -180 AND lng <= 180)),
    -- A position exists exactly when the row is DONE.
    CONSTRAINT address_location_done CHECK ((status = 'DONE') = (lat IS NOT NULL AND lng IS NOT NULL))
);

CREATE INDEX address_location_queue ON address_location (status, created_at);
